Here is a C++ program that finds the nth Fibonacci number using recursion:

```cpp
#include <iostream>
using namespace std;

int fibonacci(int n) {
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return 1;
    }

    int a = 0, b = 1;
    int result;

    result = a;
    a = b;
    b = a + b;

    for (int i = 2; i <= n; i++) {
        result += a;
        a = b;
        b = a + b;
    }

    return result;
}

int main() {
    int n;
    cout << "Enter the nth Fibonacci number: " << endl;
    cin >> n;
    cout << "The nth Fibonacci number is: " << fibonacci(n) << endl;
    return 0;
}
```

